const cfg = $('Config').first().json;
const cutoff = Date.now() - cfg.lookback_days * 86400000;
const pick = (r, keys) => { for (const k of keys) if (r[k] !== undefined && r[k] !== '') return r[k]; return ''; };
let rows = items.map(i => i.json).map(r => ({
  text: String(pick(r, ['review','Review','content','Content','review_text','text','body'])).replace(/\s+/g,' ').trim(),
  rating: pick(r, ['rating','Rating','score','Score','stars']),
  date: pick(r, ['date','Date','at','created_at','review_date'])
})).filter(r => r.text.length > 15);
// keep only last N days when the date column is readable
rows = rows.filter(r => { const t = Date.parse(r.date); return isNaN(t) || t >= cutoff; });
rows = rows.slice(0, cfg.max_reviews);
const reviews_text = rows.map((r, i) => `[${i+1}] (rating ${r.rating || 'n/a'}) ${r.text.slice(0, 300)}`).join('\n');
return [{ json: { product_name: cfg.product_name, lookback_days: cfg.lookback_days, review_count: rows.length, reviews_text } }];

