const cfg = $('Config').first().json;
const t = $('Parse themes').first().json;
const pulse = ($('Pulse LLM').first().json.text || '').trim();
let ex;
try { ex = JSON.parse(($('Explainer LLM').first().json.text || '').replace(/```json|```/g, '').trim()); }
catch (e) { ex = { bullets: [], source_links: [] }; }
const bullets = (ex.bullets || []).slice(0, 6);
const links = [cfg.official_link_1, cfg.official_link_2];
const date = new Date().toISOString().slice(0, 10);
const norm = s => String(s).toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const corpus = norm($('Prep reviews').first().json.reviews_text);
const checks = {
  pulse_words: pulse.split(/\s+/).filter(Boolean).length,
  pulse_within_250: pulse.split(/\s+/).filter(Boolean).length <= 250,
  bullets_within_6: bullets.length > 0 && bullets.length <= 6,
  two_source_links: links.every(l => l && !l.startsWith('REPLACE')),
  quotes_found_in_reviews: t.quotes.map(q => corpus.includes(norm(q)))
};
const explanation = bullets.map(b => '- ' + b).join('\n') + '\n\nSources:\n' + links.join('\n') + '\nLast checked: ' + date;
const email_subject = 'Weekly Product Pulse + Customer Clarification - ' + date;
const email_body = pulse + '\n\n---\nFee explanation (support snippet)\n\n' + explanation;
return [{ json: {
  date, top_themes: t.top_themes, weekly_pulse: pulse,
  identified_fee_issue: t.fee_issue, explanation_bullets: bullets, source_links: links,
  last_checked: date, explanation, email_subject, email_body, email_to: cfg.email_to, doc_id: cfg.doc_id, checks
} }];

